/**
 * WARD v0.2 golden vectors — sourced verbatim from the spec repo's
 * examples/single-chain and examples/meta-chain (SPEC.md §4.4, VERIFICATION.md
 * §3 Step 2). Every hash, payload_hash and signature in these fixtures is
 * real (generated by ward/tools/gen-examples.mjs), not fabricated. This suite
 * proves the SDK's v0.2 canonical-JSON hash scheme against a source outside
 * this repo, mirroring the existing external-vectors.test.ts pattern for v0.1.
 */

import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { genesisHash, chainHashV2, payloadHash, canonicalize } from '../src/crypto.js';
import { verifyChain } from '../src/verify.js';
import { publicKeyFromPem, verifyTipSignature } from '../src/sign.js';
import type { WardEntry, WardTip, VerificationResult } from '../src/types.js';

const FIX = join(dirname(fileURLToPath(import.meta.url)), 'fixtures', 'spec-v0.2');
const load = <T>(...parts: string[]): T => JSON.parse(readFileSync(join(FIX, ...parts), 'utf8')) as T;

describe('spec v0.2 golden vectors — single-chain', () => {
  const chainDesc = load<{ chain_id: string; genesis_hash: string; head_chain_hash: string }>(
    'single-chain',
    'chain.json',
  );
  const e1 = load<WardEntry>('single-chain', 'entry-1.json');
  const e2 = load<WardEntry>('single-chain', 'entry-2.json');
  const e3 = load<WardEntry>('single-chain', 'entry-3.json');
  const sources = load<Record<string, unknown>>('single-chain', 'source-events.json');
  const tip = load<WardTip>('single-chain', 'tip.json');
  const expectedResult = load<VerificationResult>('single-chain', 'verification-result.json');
  const pubKey = publicKeyFromPem(
    readFileSync(join(FIX, 'ward-example-key-v0.2-pubkey.pem'), 'utf8'),
  );

  it('genesis_hash matches SPEC §4.3', () => {
    expect(genesisHash(chainDesc.chain_id)).toBe(chainDesc.genesis_hash);
  });

  it('every entry chain_hash recomputes under the v0.2 canonical scheme (SPEC §4.4)', () => {
    for (const e of [e1, e2, e3]) {
      const recomputed = chainHashV2({
        wardVersion: e.ward_version,
        wardEntryId: e.ward_entry_id,
        chainId: e.chain_id,
        seq: e.seq,
        witnessedAt: e.witnessed_at,
        sourceKind: e.source_kind,
        sourceId: e.source_id,
        payloadHash: e.payload_hash,
        prevChainHash: e.prev_chain_hash,
        issuerId: e.issuer_id,
      });
      expect(recomputed).toBe(e.chain_hash);
    }
  });

  it('links are unbroken and the head matches the chain descriptor', () => {
    expect(e1.prev_chain_hash).toBe(chainDesc.genesis_hash);
    expect(e2.prev_chain_hash).toBe(e1.chain_hash);
    expect(e3.prev_chain_hash).toBe(e2.chain_hash);
    expect(chainDesc.head_chain_hash).toBe(e3.chain_hash);
  });

  it('payload_hash matches canonical JSON of the real source events', () => {
    expect(payloadHash(sources['aee-env-001'])).toBe(e1.payload_hash);
    expect(payloadHash(sources['aocl-dec-002'])).toBe(e2.payload_hash);
    expect(payloadHash(sources['volt-bundle-003'])).toBe(e3.payload_hash);
  });

  it('tip signature verifies against the published documentation public key', () => {
    expect(tip.tip_chain_hash).toBe(e3.chain_hash);
    expect(tip.key_id).toBe('ed25519:sha256:765fe10404e81eb5');
    expect(verifyTipSignature(tip.tip_chain_hash, tip.sig!, pubKey)).toBe(true);
  });

  it('verifyChain reproduces the exact published verification-result.json', () => {
    // The fixture's key_id ("ed25519:sha256:<...>") is the spec-doc DID-like
    // scheme (ward/tools/gen-examples.mjs), not this SDK's own fingerprint
    // convention (SPEC-POINTERS.md documents key_id derivation as a spec
    // gap). Bind identity out of band via expectedKeyId, as the SDK's own
    // docs recommend for opaque/DID key_ids.
    const result = verifyChain(chainDesc.chain_id, [e1, e2, e3], {
      tips: [tip],
      publicKey: pubKey,
      expectedKeyId: tip.key_id,
    });
    expect(result).toEqual(expectedResult);
  });
});

describe('spec v0.2 golden vectors — meta-chain', () => {
  const chainDesc = load<{ chain_id: string; genesis_hash: string; head_chain_hash: string }>(
    'meta-chain',
    'chain.json',
  );
  const e1 = load<WardEntry>('meta-chain', 'entry-1.json');
  const e2 = load<WardEntry>('meta-chain', 'entry-2.json');
  const tips = load<Record<string, WardTip>>('meta-chain', 'sub-chain-tips.json');

  it('genesis_hash matches SPEC §4.3', () => {
    expect(genesisHash(chainDesc.chain_id)).toBe(chainDesc.genesis_hash);
  });

  it('every entry chain_hash recomputes under the v0.2 canonical scheme', () => {
    for (const e of [e1, e2]) {
      const recomputed = chainHashV2({
        wardVersion: e.ward_version,
        wardEntryId: e.ward_entry_id,
        chainId: e.chain_id,
        seq: e.seq,
        witnessedAt: e.witnessed_at,
        sourceKind: e.source_kind,
        sourceId: e.source_id,
        payloadHash: e.payload_hash,
        prevChainHash: e.prev_chain_hash,
        issuerId: e.issuer_id,
      });
      expect(recomputed).toBe(e.chain_hash);
    }
  });

  it('meta-chain source_id uses the reserved "::" delimiter (SPEC §5.2, §13.3)', () => {
    expect(e1.source_id).toBe('ward:org/quox/env/production::1');
    expect(e2.source_id).toBe('ward:org/quox/env/staging::3');
  });

  it('payload_hash matches canonical JSON of the real witnessed sub-chain tips', () => {
    expect(payloadHash(tips['tip-prod-001'])).toBe(e1.payload_hash);
    expect(payloadHash(tips['tip-stg-001'])).toBe(e2.payload_hash);
  });

  it('the meta-chain verifies INTACT end to end', () => {
    const result = verifyChain(chainDesc.chain_id, [e1, e2]);
    expect(result.status).toBe('INTACT');
    if (result.status === 'INTACT') {
      expect(result.head_chain_hash).toBe(chainDesc.head_chain_hash);
      expect(result.ward_version).toBe('0.2');
    }
  });
});

describe('canonicalize — WARD-CANON-1 (SPEC §3.2)', () => {
  it('throws on non-finite numbers', () => {
    expect(() => canonicalize({ x: NaN })).toThrow();
    expect(() => canonicalize({ x: Infinity })).toThrow();
    expect(() => canonicalize({ x: -Infinity })).toThrow();
  });

  it('omits keys with undefined values rather than emitting null', () => {
    expect(canonicalize({ a: 1, b: undefined })).toBe('{"a":1}');
  });

  it('renders integers without a trailing .0 and without exponent notation', () => {
    expect(canonicalize(100)).toBe('100');
    expect(canonicalize(1)).toBe('1');
  });

  it('rejects a non-NFC string rather than silently normalizing it (rule 3)', () => {
    const nfd = 'é'; // "e" + combining acute accent (NFD, not NFC)
    const nfc = 'é'; // precomposed (already NFC)
    expect(() => canonicalize(nfd)).toThrow(/NFC/);
    expect(() => canonicalize(nfc)).not.toThrow();
  });

  it('rejects an unpaired surrogate (not well-formed Unicode, rule 3)', () => {
    const unpairedHigh = '\uD800';
    const unpairedLow = '\uDC00';
    expect(() => canonicalize(unpairedHigh)).toThrow();
    expect(() => canonicalize(unpairedLow)).toThrow();
    // A valid surrogate pair (an actual supplementary-plane character) is fine.
    expect(() => canonicalize('𐀀')).not.toThrow();
  });

  it('bounds integers to +/-(2^53 - 1) (rule 4)', () => {
    expect(() => canonicalize(Number.MAX_SAFE_INTEGER)).not.toThrow();
    expect(() => canonicalize(-Number.MAX_SAFE_INTEGER)).not.toThrow();
    expect(() => canonicalize(Number.MAX_SAFE_INTEGER + 1)).toThrow();
  });

  it('sorts object keys by UTF-8 byte order, not JS default UTF-16 code-unit order (rule 2)', () => {
    // U+E000 (BMP private use, 3 UTF-8 bytes: EE 80 80) sorts BEFORE
    // U+10000 (supplementary plane, 4 UTF-8 bytes: F0 90 80 80) in UTF-8 byte
    // order, but JS's default string comparison (UTF-16 code units) puts the
    // surrogate-pair string first because 0xD800 < 0xE000. This is the exact
    // counter-example SPEC.md §3.2 rule 2 calls out.
    const bmpPrivateUse = '';
    const supplementaryPlane = '𐀀'; // U+10000
    // Sanity-check the JS-native (wrong) order really would invert this.
    expect([supplementaryPlane, bmpPrivateUse].sort()).toEqual([supplementaryPlane, bmpPrivateUse]);
    const c = canonicalize({ [supplementaryPlane]: 1, [bmpPrivateUse]: 2 });
    expect(c.indexOf(JSON.stringify(bmpPrivateUse))).toBeLessThan(c.indexOf(JSON.stringify(supplementaryPlane)));
  });
});

describe('chainHashV2 — hash body exactly 10 members, no extras/absent/null (SPEC §4.4)', () => {
  const base = {
    wardVersion: '0.2',
    wardEntryId: 'e1',
    chainId: 'ward:org/quox/env/staging',
    seq: 1,
    witnessedAt: '2026-01-01T00:00:00.000Z',
    sourceKind: 'AEE',
    sourceId: 's1',
    payloadHash: 'a'.repeat(64),
    prevChainHash: 'b'.repeat(64),
    issuerId: 'issuer-1',
  };

  it('computes normally when all 10 fields are present', () => {
    expect(() => chainHashV2(base)).not.toThrow();
  });

  it('throws rather than silently omitting a missing required field', () => {
    const { issuerId: _drop, ...rest } = base;
    expect(() => chainHashV2(rest as typeof base)).toThrow();
  });

  it('throws rather than silently hashing a null required field', () => {
    const withNull = { ...base, issuerId: null as unknown as string };
    expect(() => chainHashV2(withNull)).toThrow();
  });
});
